select count(*) as cust_cnt
from ads_cust_info_d
where data_dt='20260531';

select round(avg(cust_age),1) as avg_age
from ads_cust_info_d
where data_dt='20260531';

select count(*) as prdt_cnt
from dim_product
where prdt_type_name='A股';

select count(*) as prdt_cnt
from dim_product
where prdt_type_name='ETF';

select count(distinct pty_id) as cust_cnt
from dwd_cust_hold_d
where data_dt='20260331';

select sum(mkt_val) as tot_mkt_val
from dwd_cust_hold_d
where data_dt='20260331';

select count(distinct pty_id) as cust_cnt
from dwd_cust_tran_d
where data_dt between '20260101' and '20260331';

select sum(buy_amt) as tot_buy_amt
from dwd_cust_tran_d
where data_dt between '20260101' and '20260331';

select sum(sell_amt) as tot_sell_amt
from dwd_cust_tran_d
where data_dt between '20260101' and '20260331';

select sum(nm_tot_aset) as tot_aset
from dws_cust_aset_d
where data_dt='20260331';

select round(avg(nm_tot_aset),2) as avg_aset
from dws_cust_aset_d
where data_dt='20260331';

select sum(cash_in) as tot_cash_in
from dws_cust_fin_d
where data_dt between '20260101' and '20260331';
